let text = $input.first().json.output[0].content[0].text;

text = text
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(text);
} catch (error) {
  throw new Error(
    'LeonardoのJSON解析に失敗しました。\n' +
    'エラー: ' + error.message + '\n\n' +
    '受信内容:\n' + text
  );
}

if (!parsed.tasks || !Array.isArray(parsed.tasks)) {
  throw new Error('Leonardoの出力にtasks配列がありません');
}

const agentMap = {
  LEONARDO: 1,
  SUN_TZU: 2,
  KONGMING: 3,
  SHAKESPEARE: 4,
  MICHELANGELO: 5,
  NAPOLEON: 6,
  DARWIN: 7
};

return parsed.tasks.map((task, index) => ({
  json: {
    task_code: `TSK-${Date.now()}-${index + 1}`,

    project_id: 1,
    workflow_run_id: null,
    parent_task_id: null,

    assigned_agent_id: agentMap[task.assigned_agent] ?? null,
    next_agent_id: agentMap[task.next_agent] ?? null,

    task_type: task.task_type ?? '',
    title: task.title ?? '',
    goal: task.goal ?? '',
    instructions: task.instructions ?? '',

    constraints_json: JSON.stringify(task.constraints ?? []),
    required_outputs_json: JSON.stringify(task.required_outputs ?? []),

    status: 'pending',
    quality_threshold: task.quality_threshold ?? 80,

    revision_count: 0,
    max_revisions: 3
  }
}));

