// 孫子に渡したタスク情報をSQLノードから取得
const task = $('Execute a SQL query').first().json;

// 孫子（OpenAI）の回答を取得
const ai = $input.first().json;

// OpenAIの回答本文
const content = ai.output[0].content[0].text;

// JSONとして解析
let parsedContent;

try {
  parsedContent = JSON.parse(content);
} catch (error) {
  parsedContent = {
    raw_text: content
  };
}

// artifactsテーブル登録用データを作成
return [
  {
    json: {
      artifact_code: 'ART-' + Date.now(),

      project_id: task.project_id,
      task_id: task.task_id,

      created_by_agent_id: 2,

      artifact_type: 'market_research',

      title: task.title,

      summary: parsedContent.summary ?? '孫子による市場調査結果',

      content: content,

      content_json: JSON.stringify(parsedContent),

      version: task.prompt_version ?? '1.0.0',

      status: 'reviewing'
    }
  }
];

